// ─── harness ──────────────────────────────────────────────────────────────────
const P = (id, card, controller = "user", extra = {}) => ({ ...createPermanent({ id, card: { id: `c-${id}`, ...card }, controller, summoningSick: false }), ...extra });
const H = (id, card) => ({ ...card, id });
// Attach aura `auraId` to host `hostId` on a list of permanents (both sides of the link, as the engine stores it).
const attach = (perms, auraId, hostId) => perms.map((p) => (p.id === auraId ? { ...p, attachedTo: hostId } : p.id === hostId ? { ...p, attachments: [...(p.attachments || []), auraId] } : p));
function board({ user = [], ai = [], hand = [], aiHand = [], lib = [], pool = {}, aiPool = {} } = {}) {
  const g = createGameState({ userDeck: [], aiDeck: [] });
  return { ...g, turn: 5, activePlayer: "user", priorityHolder: "user", phase: "precombat-main", step: "main", stack: [], pendingTriggers: [], consecutivePasses: 0,
    players: { ...g.players,
      user: { ...g.players.user, battlefield: user, hand, manaPool: { ...g.players.user.manaPool, ...pool }, library: lib.map((card, i) => ({ ...card, id: `lib${i}` })) },
      ai: { ...g.players.ai, battlefield: ai, hand: aiHand, manaPool: { ...g.players.ai.manaPool, ...aiPool }, library: [1, 2, 3].map((i) => ({ ...GRIZZLY_BEARS, id: `ai-lib${i}` })) } } };
}
const offers = (s, who, cardId) => legalActionsForPlayer(s, who).filter((a) => a.kind === "cast-spell" && a.cardId === cardId);
// Cast through the real offer → dispatch path; `pick` narrows the offer (a sacrifice victim, a target).
const cast = (s, cardId, pick = () => true, who = "user") => {
  const offer = offers(s, who, cardId).find(pick);
  expect(offer).toBeTruthy();
  return dispatchAction(s, offer);
};
// Activate an ability of `permId` on its controller's own priority and resolve it; priority returns to the user.
const activate = (s, who, permId, pick = () => true) => {
  const as = { ...s, activePlayer: who, priorityHolder: who };
  const offer = legalActionsForPlayer(as, who).find((a) => a.kind === "activate-ability" && a.permanentId === permId && pick(a));
  expect(offer).toBeTruthy();
  return { ...resolveTopOfStack(dispatchAction(as, offer)), activePlayer: "user", priorityHolder: "user" };
};
const ids = (s, who) => s.players[who].battlefield.map((p) => p.id).sort();
const names = (cards) => cards.map((c) => c.name).sort();
const errors = (s) => (s.log || []).filter((e) => e.kind === "stack-resolve-error");
const ctxUser = { controller: "user", sourceId: null, cardName: "test", targets: [] };

// Kindred Dominance: {5}{B}{B} from the pool, cast and resolved.
const KD_POOL = { B: 7 };
const dominate = (s) => resolveTopOfStack(cast(s, "kd"));
const kdBoard = (o = {}) => board({ hand: [H("kd", KINDRED_DOMINANCE)], pool: KD_POOL, ...o });
const kdLog = (s) => (s.log || []).filter((e) => e.effect === "destroy-not-chosen-type").map((e) => ({ chosenType: e.chosenType, notOfType: e.notOfType, ofType: e.ofType }));

// Eldritch Evolution: {1}{G}{G} from the pool; the cast sacrifices `victimId`; the search pauses on the tutor choice.
const EE_POOL = { G: 3 };
const EE_LIBRARY = [LLANOWAR_ELVES, GRIZZLY_BEARS, CENTAUR_COURSER, HILL_GIANT, SIEGE_MASTODON, COLOSSAL_DREADMAW, WALKING_BALLISTA, SOL_RING, FOREST];
const eeBoard = (o = {}) => board({ hand: [H("ee", ELDRITCH_EVOLUTION)], pool: EE_POOL, lib: EE_LIBRARY, ...o });
const evolve = (s, victimId) => resolveTopOfStack(cast(s, "ee", (a) => a.sacCreatureId === victimId));
const candidates = (s) => (s.pendingChoice?.kind === "tutor-search" ? names(s.pendingChoice.candidates) : null);
const fetch = (s, name) => resolveTutorChoice(s, name == null ? null : s.pendingChoice.candidates.find((c) => c.name === name).id);

describe("the cards and their parse", () => {
  it("classify: Kindred Dominance, Kindred Judgment and Eldritch Evolution native-spell; the neighbours this slice must not touch stay where they were", () => {
    const row = Object.fromEntries(Object.entries({ KINDRED_DOMINANCE, KINDRED_JUDGMENT, ELDRITCH_EVOLUTION, NEOFORM, HARSH_MERCY, EXTINCTION, CRIPPLING_FEAR, RAISE_THE_PALISADE }).map(([k, c]) => [k, classifyCard(c)]));
    console.log("  WITNESS classify", JSON.stringify(row)); // vitest 4 needs --disable-console-intercept
    expect(row).toEqual({ KINDRED_DOMINANCE: "native-spell", KINDRED_JUDGMENT: "native-spell", ELDRITCH_EVOLUTION: "native-spell",
      NEOFORM: "arbiter-spell", HARSH_MERCY: "arbiter-spell", EXTINCTION: "arbiter-spell", CRIPPLING_FEAR: "arbiter-spell", RAISE_THE_PALISADE: "arbiter-spell" });
  });

  it("the Kindred Dominance parse: ONE atom, no target, not an X spell — and both printings parse alike", () => {
    const p = parseEffectProgram(KINDRED_DOMINANCE);
    expect({ confidence: programConfidence(p), atoms: p.atoms, xSpell: p.xSpell, costs: p.additionalCosts, selfExile: p.selfExile })
      .toEqual({ confidence: "high", atoms: [{ op: "destroy-not-chosen-type", targetType: null }], xSpell: false, costs: undefined, selfExile: undefined });
    expect(parseEffectProgram(KINDRED_JUDGMENT).atoms).toEqual(p.atoms);
    expect(typeof ATOM_RESOLVERS["destroy-not-chosen-type"]).toBe("function");
  });

  it("the Eldritch Evolution parse: the sacrifice cost, ONE capped tutor to the battlefield, the self-exile stamp, not an X spell", () => {
    const p = parseEffectProgram(ELDRITCH_EVOLUTION);
    expect({ confidence: programConfidence(p), atoms: p.atoms, xSpell: p.xSpell, costs: p.additionalCosts, selfExile: p.selfExile }).toEqual({
      confidence: "high",
      atoms: [{ op: "tutor", filter: { groups: [["creature"]], mvMaxFromSacrificedPlus: 2 }, filterLabel: "creature card with mana value 2 plus the sacrificed creature's or less", destination: "battlefield", entersTapped: false, targetType: null }],
      xSpell: false, costs: [{ kind: "sacrifice", sacType: "creature" }], selfExile: true,
    });
  });

  it("near misses stay unparsed: either sentence alone, another chooser, another verb, another filter, a rider before or after", () => {
    const atoms = (clause) => parseEffectClause(clause, "Sorcery")?.atoms ?? [];
    expect({
      chooseOnly: atoms("Choose a creature type."),
      destroyOnly: atoms("Destroy all creatures that aren't of the chosen type."),
      eachPlayer: atoms("Each player chooses a creature type. Destroy all creatures that aren't of a type chosen this way."),
      ofTheType: atoms("Choose a creature type. Destroy all creatures of the chosen type."),
      exile: atoms("Choose a creature type. Exile all creatures that aren't of the chosen type."),
      riderAfter: atoms("Choose a creature type. Destroy all creatures that aren't of the chosen type. You gain 2 life."),
      riderBefore: atoms("You gain 2 life. Choose a creature type. Destroy all creatures that aren't of the chosen type."),
    }).toEqual({ chooseOnly: [], destroyOnly: [], eachPlayer: [], ofTheType: [], exile: [], riderAfter: [], riderBefore: [] });
    expect({
      searchOnly: atoms("Search your library for a creature card with mana value X or less, where X is 2 plus the sacrificed creature's mana value."),
      putOnly: atoms("Put that card onto the battlefield, then shuffle."),
      artifact: atoms("Search your library for an artifact card with mana value X or less, where X is 2 plus the sacrificed creature's mana value. Put that card onto the battlefield, then shuffle."),
      power: atoms("Search your library for a creature card with mana value X or less, where X is 2 plus the sacrificed creature's power. Put that card onto the battlefield, then shuffle."),
      toHand: atoms("Search your library for a creature card with mana value X or less, where X is 2 plus the sacrificed creature's mana value. Put that card into your hand, then shuffle."),
      riderAfter: atoms("Search your library for a creature card with mana value X or less, where X is 2 plus the sacrificed creature's mana value. Put that card onto the battlefield, then shuffle. You gain 2 life."),
      riderBefore: atoms("You gain 2 life. Search your library for a creature card with mana value X or less, where X is 2 plus the sacrificed creature's mana value. Put that card onto the battlefield, then shuffle."),
    }).toEqual({ searchOnly: [], putOnly: [], artifact: [], power: [], toHand: [], riderAfter: [], riderBefore: [] });
  });

  it("the AI holds Kindred Dominance like any symmetric wipe, and it unlocks as a creature wipe when clearly behind", () => {
    const p = parseEffectProgram(KINDRED_DOMINANCE);
    expect({ held: programContainsMassRemoval(p), creatureWipe: programContainsCreatureMassRemoval(p) }).toEqual({ held: true, creatureWipe: true });
  });

  it("SYNTHETIC SHAPE (the rider stamp): a \"can't be regenerated\" sentence the parse text strips is put back on the atom, and the destroy honours it", () => {
    const p = parseEffectClause("Choose a creature type. Destroy all creatures that aren't of the chosen type. They can't be regenerated.", "Sorcery");
    expect(p.atoms).toEqual([{ op: "destroy-not-chosen-type", targetType: null, cannotRegenerate: true }]);
    const s0 = board({ ai: [P("drudge", DRUDGE_SKELETONS, "ai", { regenShields: 1 })] });
    const out = (atom) => ids(resolveAtom(s0, atom, ctxUser), "ai");
    expect({ printed: out(parseEffectProgram(KINDRED_DOMINANCE).atoms[0]), withRider: out(p.atoms[0]) }).toEqual({ printed: ["drudge"], withRider: [] });
  });
});

describe("⭐ Kindred Dominance — cast, resolved", () => {
  it("⭐ the caster's creatures share a type and the opponent's do not: the opponent's board is destroyed, the caster's stays", () => {
    // user: Llanowar Elves, Fyndhorn Elves (Elf Druid), Elvish Visionary (Elf Shaman) → Elf ×3. ai: a Bear, a Goblin Berserker, a Giant.
    const s0 = kdBoard({ user: [P("llanowar", LLANOWAR_ELVES), P("fyndhorn", FYNDHORN_ELVES), P("visionary", ELVISH_VISIONARY)],
      ai: [P("bears", GRIZZLY_BEARS, "ai"), P("goblin", RAGING_GOBLIN, "ai"), P("giant", HILL_GIANT, "ai")] });
    const onStack = cast(s0, "kd");
    const s = resolveTopOfStack(onStack);
    const row = { castTargets: onStack.stack[0].payload.params.targets, user: ids(s, "user"), ai: ids(s, "ai"), userGraveyard: names(s.players.user.graveyard), aiGraveyard: names(s.players.ai.graveyard),
      log: kdLog(s), stack: s.stack.length, pending: s.pendingChoice ?? null, errors: errors(s).length };
    console.log("  WITNESS sharedType", JSON.stringify(row));
    expect(row).toEqual({ castTargets: [], user: ["fyndhorn", "llanowar", "visionary"], ai: [], userGraveyard: ["Kindred Dominance"], aiGraveyard: ["Grizzly Bears", "Hill Giant", "Raging Goblin"],
      log: [{ chosenType: "elf", notOfType: 3, ofType: 3 }], stack: 0, pending: null, errors: 0 });
  });

  it("⭐ every creature type survives any choice: a changeling on either side, an animated Mutavault, and every creature under Maskwood Nexus", () => {
    // A: both players hold a changeling; the opponent also animates Mutavault ("a 2/2 creature with all creature types").
    const a0 = activate(kdBoard({ user: [P("llanowar", LLANOWAR_ELVES), P("colossus", CHAMELEON_COLOSSUS)],
      ai: [P("automaton", UNIVERSAL_AUTOMATON, "ai"), P("vault", MUTAVAULT, "ai"), P("bears", GRIZZLY_BEARS, "ai")], aiPool: { C: 1 } }), "ai", "vault");
    const a = dominate(a0);
    // B: the caster's Maskwood Nexus makes the caster's creatures every creature type — a Bear and a Giant, no type shared.
    const b0 = kdBoard({ user: [P("nexus", MASKWOOD_NEXUS), P("bears", GRIZZLY_BEARS), P("giant", HILL_GIANT)], ai: [P("corpse", WALKING_CORPSE, "ai"), P("goblin", RAGING_GOBLIN, "ai")] });
    const b = dominate(b0);
    const row = {
      changelings: { vaultIsEveryType: permIsEveryCreatureType(a0, "vault"), user: ids(a, "user"), ai: ids(a, "ai"), log: kdLog(a) },
      nexus: { bearsAreEveryType: permIsEveryCreatureType(b0, "bears"), user: ids(b, "user"), ai: ids(b, "ai"), log: kdLog(b) },
    };
    console.log("  WITNESS everyType", JSON.stringify(row));
    expect(row).toEqual({
      changelings: { vaultIsEveryType: true, user: ["colossus", "llanowar"], ai: ["automaton", "vault"], log: [{ chosenType: "druid", notOfType: 1, ofType: 4 }] },
      // nothing the caster controls names a type, so the pick is the type that spares nothing of the opponent's
      nexus: { bearsAreEveryType: true, user: ["bears", "giant", "nexus"], ai: [], log: [{ chosenType: "advisor", notOfType: 2, ofType: 2 }] },
    });
  });

  it("⭐ Changeling is a copiable value: Impossible Man (an Alien Shapeshifter) as a copy of Chameleon Colossus is every creature type and is spared; as itself it is destroyed", () => {
    const base = () => kdBoard({ user: [P("llanowar", LLANOWAR_ELVES)], ai: [P("man", IMPOSSIBLE_MAN, "ai"), P("colossus", CHAMELEON_COLOSSUS, "ai")], aiPool: { U: 3 } });
    const copied = activate(base(), "ai", "man", (a) => (a.targets || []).some((t) => t.id === "colossus"));
    const row = { asCopy: { everyType: permIsEveryCreatureType(copied, "man"), ai: ids(dominate(copied), "ai") }, asItself: { everyType: permIsEveryCreatureType(base(), "man"), ai: ids(dominate(base()), "ai") } };
    console.log("  WITNESS copiedChangeling", JSON.stringify(row));
    expect(row).toEqual({ asCopy: { everyType: true, ai: ["colossus", "man"] }, asItself: { everyType: false, ai: ["colossus"] } });
  });

  it("⭐ the destroy is the shared one: indestructible, a regeneration shield and umbra armor each keep a creature of another type", () => {
    const ai = attach([P("myr", DARKSTEEL_MYR, "ai"), P("drudge", DRUDGE_SKELETONS, "ai", { regenShields: 1 }), P("bears", GRIZZLY_BEARS, "ai", { damageMarked: 1 }), P("umbra", HYENA_UMBRA, "ai"), P("giant", HILL_GIANT, "ai")], "umbra", "bears");
    const s = dominate(kdBoard({ user: [P("llanowar", LLANOWAR_ELVES)], ai }));
    const drudge = s.players.ai.battlefield.find((p) => p.id === "drudge");
    const bears = s.players.ai.battlefield.find((p) => p.id === "bears");
    const row = { user: ids(s, "user"), ai: ids(s, "ai"), aiGraveyard: names(s.players.ai.graveyard), drudge: { shields: drudge?.regenShields ?? 0, tapped: drudge?.tapped }, bearsDamage: bears?.damageMarked, log: kdLog(s) };
    console.log("  WITNESS sharedDestroy", JSON.stringify(row));
    expect(row).toEqual({ user: ["llanowar"], ai: ["bears", "drudge", "myr"], aiGraveyard: ["Hill Giant", "Hyena Umbra"], drudge: { shields: 0, tapped: true }, bearsDamage: 0,
      log: [{ chosenType: "druid", notOfType: 4, ofType: 1 }] });
  });

  it("⭐ only creatures: a bestowed Aura and a Saga whose back face is a creature are not creatures and are not destroyed", () => {
    // ai: Colossal Dreadmaw wearing a bestowed Boon Satyr (an Aura while attached, CR 702.103), and Fable of the Mirror-Breaker.
    const s0 = kdBoard({ user: [P("llanowar", LLANOWAR_ELVES)],
      ai: [P("maw", COLOSSAL_DREADMAW, "ai", { attachments: ["satyr"] }), P("satyr", BOON_SATYR, "ai", { attachedTo: "maw", bestowed: true }), P("fable", FABLE, "ai", { counters: { lore: 1 } })] });
    const s = dominate(s0);
    const row = { before: { satyrIsCreature: permanentIsCreature(s0, "satyr"), fableIsCreature: permanentIsCreature(s0, "fable") }, ai: ids(s, "ai"), aiGraveyard: names(s.players.ai.graveyard),
      satyrIsCreatureAfter: permanentIsCreature(s, "satyr"), log: kdLog(s) };
    console.log("  WITNESS onlyCreatures", JSON.stringify(row));
    expect(row).toEqual({ before: { satyrIsCreature: false, fableIsCreature: false }, ai: ["fable", "satyr"], aiGraveyard: ["Colossal Dreadmaw"], satyrIsCreatureAfter: true,
      log: [{ chosenType: "druid", notOfType: 1, ofType: 1 }] });
  });

  it("⭐ one event: a Blood Artist destroyed with the rest sees every creature that died", () => {
    const s = dominate(kdBoard({ user: [P("llanowar", LLANOWAR_ELVES), P("fyndhorn", FYNDHORN_ELVES)], ai: [P("artist", BLOOD_ARTIST, "ai"), P("bears", GRIZZLY_BEARS, "ai"), P("giant", HILL_GIANT, "ai")] }));
    const row = { died: s.players.ai.graveyard.length, artistTriggers: s.stack.filter((o) => o.source?.name === "Blood Artist").length + (s.pendingTriggers || []).filter((t) => t.sourceName === "Blood Artist" || t.source?.name === "Blood Artist").length };
    console.log("  WITNESS oneEvent", JSON.stringify(row));
    expect(row).toEqual({ died: 3, artistTriggers: 3 });
  });

  it("Kindred Judgment is the same card in white", () => {
    const s0 = board({ hand: [H("kj", KINDRED_JUDGMENT)], pool: { W: 7 }, user: [P("llanowar", LLANOWAR_ELVES), P("fyndhorn", FYNDHORN_ELVES)], ai: [P("bears", GRIZZLY_BEARS, "ai")] });
    const s = resolveTopOfStack(cast(s0, "kj"));
    expect({ user: ids(s, "user"), ai: ids(s, "ai"), userGraveyard: names(s.players.user.graveyard), log: kdLog(s) })
      .toEqual({ user: ["fyndhorn", "llanowar"], ai: [], userGraveyard: ["Kindred Judgment"], log: [{ chosenType: "druid", notOfType: 1, ofType: 2 }] });
  });
});

describe("⭐ of the chosen type — a creature's CURRENT creature types", () => {
  it("⭐ a type an effect ADDED counts: Adaptive Automaton (a Construct) that chose Elf is an Elf and is spared", () => {
    // The chosen type is stamped as the entry stamps it (enterReplacements: perm.chosenType); layer 4 adds it to the Construct.
    const s0 = kdBoard({ user: [P("llanowar", LLANOWAR_ELVES), P("fyndhorn", FYNDHORN_ELVES), P("automaton", ADAPTIVE_AUTOMATON, "user", { chosenType: "Elf" })], ai: [P("bears", GRIZZLY_BEARS, "ai")] });
    const s = dominate(s0);
    const row = { automatonTypes: permanentCreatureTypes(s0, "automaton"), user: ids(s, "user"), ai: ids(s, "ai"), log: kdLog(s) };
    console.log("  WITNESS addedType", JSON.stringify(row));
    expect(row).toEqual({ automatonTypes: ["construct", "elf"], user: ["automaton", "fyndhorn", "llanowar"], ai: [], log: [{ chosenType: "elf", notOfType: 1, ofType: 3 }] });
  });

  it("⭐ a type an effect REPLACED does not: Mistform Dreamer (printed Illusion) that became a Bear is destroyed when Illusion is chosen", () => {
    // ai activates Mistform Dreamer ("becomes the creature type of your choice until end of turn"; the engine picks the type of
    // its controller's other creatures — Bear). The caster holds two Illusions, so Illusion is chosen.
    const s0 = activate(kdBoard({ user: [P("mist", KROVIKAN_MIST), P("phantasm", JACES_PHANTASM)], ai: [P("dreamer", MISTFORM_DREAMER, "ai"), P("bears", GRIZZLY_BEARS, "ai")], aiPool: { C: 1 } }), "ai", "dreamer");
    const s = dominate(s0);
    const row = { dreamerTypes: permanentCreatureTypes(s0, "dreamer"), user: ids(s, "user"), ai: ids(s, "ai"), log: kdLog(s) };
    console.log("  WITNESS replacedType", JSON.stringify(row));
    expect(row).toEqual({ dreamerTypes: ["bear"], user: ["mist", "phantasm"], ai: [], log: [{ chosenType: "illusion", notOfType: 2, ofType: 2 }] });
  });

  it("⭐ a double-faced creature has its front face's types: Delver of Secrets (Human Wizard // Human Insect) is no Insect, and is a Human once", () => {
    // user: two Insects. ai: Delver of Secrets, front face up (the engine never transforms it).
    const s0 = kdBoard({ user: [P("scute", SCUTE_MOB), P("caterpillar", CAUSTIC_CATERPILLAR)], ai: [P("delver", DELVER, "ai")] });
    const s = dominate(s0);
    const row = { delverTypes: permanentCreatureTypes(s0, "delver"), typesOnceGone: permanentCreatureTypes(s, "delver"), user: ids(s, "user"), ai: ids(s, "ai"), aiGraveyard: names(s.players.ai.graveyard), log: kdLog(s) };
    console.log("  WITNESS frontFace", JSON.stringify(row));
    expect(row).toEqual({ delverTypes: ["human", "wizard"], typesOnceGone: [], user: ["caterpillar", "scute"], ai: [], aiGraveyard: ["Delver of Secrets // Insectile Aberration"], log: [{ chosenType: "insect", notOfType: 1, ofType: 2 }] });
  });

  it("SYNTHETIC LAYER EFFECT (the copy's type line): a double-faced creature that is a copy of a single-faced one has the COPIED types, not its own front face's", () => {
    // No real path reaches this (the become-a-copy offer never targets a double-faced permanent), so the layer-1 effect is
    // built directly, shaped as atoms/becomeCopy.applyBecomeCopy stores it: the caster's Delver is a copy of Llanowar Elves.
    const s0 = kdBoard({ user: [P("llanowar", LLANOWAR_ELVES), P("delver", DELVER)], ai: [P("bears", GRIZZLY_BEARS, "ai")] });
    const { state: s1 } = addContinuousEffect(s0, { layer: 1, op: "copy", copiableCard: { ...LLANOWAR_ELVES, id: "c-delver" }, affects: { mode: "self", permanentId: "delver" }, duration: { kind: "permanent" }, source: { kind: "resolution", permanentId: "delver", cardName: "synthetic" } });
    const s = dominate(s1);
    expect({ asItself: permanentCreatureTypes(s0, "delver"), asCopy: permanentCreatureTypes(s1, "delver"), user: ids(s, "user"), ai: ids(s, "ai"), log: kdLog(s) })
      .toEqual({ asItself: ["human", "wizard"], asCopy: ["elf", "druid"], user: ["delver", "llanowar"], ai: [], log: [{ chosenType: "druid", notOfType: 1, ofType: 2 }] });
  });

  it("SYNTHETIC LAYER EFFECT (the back-face guard's other half): a type a layer-4 effect adds to a double-faced creature counts, even when only its back face prints it", () => {
    const s0 = kdBoard({ user: [P("scute", SCUTE_MOB), P("caterpillar", CAUSTIC_CATERPILLAR), P("delver", DELVER)], ai: [P("bears", GRIZZLY_BEARS, "ai")] });
    const { state: s1 } = addContinuousEffect(s0, { layer: 4, op: { subtypes: ["Insect"] }, affects: { mode: "fixed", permanentIds: ["delver"] }, duration: { kind: "permanent" }, source: { kind: "resolution", permanentId: null, cardName: "synthetic" } });
    const s = dominate(s1);
    expect({ printed: permanentCreatureTypes(s0, "delver"), withEffect: permanentCreatureTypes(s1, "delver"), user: ids(s, "user"), ai: ids(s, "ai"), log: kdLog(s) })
      .toEqual({ printed: ["human", "wizard"], withEffect: ["human", "wizard", "insect"], user: ["caterpillar", "delver", "scute"], ai: [], log: [{ chosenType: "insect", notOfType: 1, ofType: 3 }] });
  });

  it("⭐ only a creature type can be chosen: a Food Golem is a Golem (Food is an artifact type, CR 205.3g); two Time Lords share the two-word type", () => {
    const a0 = kdBoard({ user: [P("ginger", GINGERBRUTE)], ai: [P("bears", GRIZZLY_BEARS, "ai")] });
    const a = dominate(a0);
    // The Tenth Doctor (Time Lord Doctor) and Missy (Time Lord Rogue): Time Lord is the one type both have.
    const b0 = kdBoard({ user: [P("doctor", TENTH_DOCTOR), P("missy", MISSY)], ai: [P("bears", GRIZZLY_BEARS, "ai")] });
    const b = dominate(b0);
    const row = { golem: { types: permanentCreatureTypes(a0, "ginger"), user: ids(a, "user"), log: kdLog(a) },
      timeLord: { types: [permanentCreatureTypes(b0, "doctor"), permanentCreatureTypes(b0, "missy")], user: ids(b, "user"), ai: ids(b, "ai"), log: kdLog(b) } };
    console.log("  WITNESS vocabulary", JSON.stringify(row));
    expect(row).toEqual({ golem: { types: ["golem"], user: ["ginger"], log: [{ chosenType: "golem", notOfType: 1, ofType: 1 }] },
      timeLord: { types: [["doctor", "time lord"], ["rogue", "time lord"]], user: ["doctor", "missy"], ai: [], log: [{ chosenType: "time lord", notOfType: 1, ofType: 2 }] } });
  });
});

