describe("⭐ Eldritch Evolution — the cost, the search, the exile", () => {
  it("⭐ sacrificing a 3-mana-value creature: creature cards of mana value 5 or less are offered; the chosen one enters; the spell is exiled", () => {
    const s0 = eeBoard({ user: [P("courser", CENTAUR_COURSER), P("bears", GRIZZLY_BEARS)] });
    const victims = offers(s0, "user", "ee").map((a) => a.sacCreatureId).sort();
    const onStack = cast(s0, "ee", (a) => a.sacCreatureId === "courser");
    const paused = resolveTopOfStack(onStack);
    const s = fetch(paused, "Siege Mastodon");
    const row = { victims, paidAtCast: { battlefield: ids(onStack, "user"), graveyard: names(onStack.players.user.graveyard), frozen: onStack.stack[0].payload.params.context.sacrificedForCost },
      candidates: candidates(paused), mayFailToFind: paused.pendingChoice.mayFailToFind,
      battlefield: s.players.user.battlefield.map((p) => p.card.name).sort(), graveyard: names(s.players.user.graveyard), exile: names(s.players.user.exile), library: s.players.user.library.length,
      stack: s.stack.length, pending: s.pendingChoice ?? null, errors: errors(s).length };
    console.log("  WITNESS evolveThree", JSON.stringify(row));
    expect(row).toEqual({ victims: ["bears", "courser"],
      paidAtCast: { battlefield: ["bears"], graveyard: ["Centaur Courser"], frozen: { power: 3, toughness: 3, manaValue: 3 } },
      // Colossal Dreadmaw (6) is over the cap; Sol Ring and Forest are not creature cards; Walking Ballista's {X}{X} is 0 (CR 107.3g)
      candidates: ["Centaur Courser", "Grizzly Bears", "Hill Giant", "Llanowar Elves", "Siege Mastodon", "Walking Ballista"], mayFailToFind: true,
      battlefield: ["Grizzly Bears", "Siege Mastodon"], graveyard: ["Centaur Courser"], exile: ["Eldritch Evolution"], library: EE_LIBRARY.length - 1,
      stack: 0, pending: null, errors: 0 });
  });

  it("⭐ the found card ENTERS: Kalonian Hydra's four +1/+1 counters are on it", () => {
    const paused = evolve(eeBoard({ user: [P("courser", CENTAUR_COURSER)], lib: [KALONIAN_HYDRA, FOREST] }), "courser");
    const s = fetch(paused, "Kalonian Hydra");
    const hydra = s.players.user.battlefield.find((p) => p.card.name === "Kalonian Hydra");
    expect({ candidates: candidates(paused), counters: hydra?.counters?.["+1/+1"], tapped: hydra?.tapped }).toEqual({ candidates: ["Kalonian Hydra"], counters: 4, tapped: false });
  });

  it("⭐ a token that is not a copy has mana value 0 (2 or less is offered); a token that is a copy has the copied mana value", () => {
    // A: Raise the Alarm's Soldier token. B: Quasiduplicate's token copy of Hill Giant (mana value 4) → 6 or less.
    const a0 = resolveTopOfStack(cast(eeBoard({ hand: [H("ee", ELDRITCH_EVOLUTION), H("alarm", RAISE_THE_ALARM)], pool: { G: 3, W: 2 } }), "alarm"));
    const soldier = a0.players.user.battlefield.find((p) => p.card?.token);
    const a = evolve(a0, soldier.id);
    const b0 = resolveTopOfStack(cast(eeBoard({ user: [P("giant", HILL_GIANT)], hand: [H("ee", ELDRITCH_EVOLUTION), H("dup", QUASIDUPLICATE)], pool: { G: 3, U: 3 } }), "dup"));
    const copy = b0.players.user.battlefield.find((p) => p.card?.token);
    const b = evolve(b0, copy.id);
    const row = { soldier: { name: soldier.card.name, cmc: soldier.card.cmc ?? null, candidates: candidates(a) }, copy: { name: copy.card.name, candidates: candidates(b) } };
    console.log("  WITNESS tokens", JSON.stringify(row));
    expect(row).toEqual({ soldier: { name: "Soldier", cmc: null, candidates: ["Grizzly Bears", "Llanowar Elves", "Walking Ballista"] },
      copy: { name: "Hill Giant", candidates: ["Centaur Courser", "Colossal Dreadmaw", "Grizzly Bears", "Hill Giant", "Llanowar Elves", "Siege Mastodon", "Walking Ballista"] } });
  });

  it("⭐ an {X} in the sacrificed creature's cost is 0, whatever it was cast for: Walking Ballista with two counters gives 2 or less", () => {
    const paused = evolve(eeBoard({ user: [P("ballista", WALKING_BALLISTA, "user", { counters: { "+1/+1": 2 }, xValue: 2 })] }), "ballista");
    expect(candidates(paused)).toEqual(["Grizzly Bears", "Llanowar Elves", "Walking Ballista"]);
  });

  it("⭐ a creature that became a copy has the copied mana value: Impossible Man (3) as a copy of Colossal Dreadmaw (6) gives 8 or less; uncopied, 5 or less", () => {
    const base = () => eeBoard({ user: [P("man", IMPOSSIBLE_MAN), P("maw", COLOSSAL_DREADMAW)], pool: { G: 3, U: 3 } });
    const copied = activate(base(), "user", "man", (a) => (a.targets || []).some((t) => t.id === "maw"));
    const row = { asCopy: candidates(evolve(copied, "man")), asItself: candidates(evolve(base(), "man")) };
    console.log("  WITNESS copyValue", JSON.stringify(row));
    expect(row).toEqual({ asCopy: ["Centaur Courser", "Colossal Dreadmaw", "Grizzly Bears", "Hill Giant", "Llanowar Elves", "Siege Mastodon", "Walking Ballista"],
      asItself: ["Centaur Courser", "Grizzly Bears", "Hill Giant", "Llanowar Elves", "Siege Mastodon", "Walking Ballista"] });
  });

  it("⭐ no legal creature card in the library: nothing is found, the library is still searched and the spell is still exiled", () => {
    const paused = evolve(eeBoard({ user: [P("bears", GRIZZLY_BEARS)], lib: [COLOSSAL_DREADMAW, SOL_RING, FOREST] }), "bears");
    const s = fetch(paused, null);
    const row = { candidates: candidates(paused), battlefield: ids(s, "user"), library: names(s.players.user.library), graveyard: names(s.players.user.graveyard), exile: names(s.players.user.exile), stack: s.stack.length, pending: s.pendingChoice ?? null };
    console.log("  WITNESS nothingFound", JSON.stringify(row));
    expect(row).toEqual({ candidates: [], battlefield: [], library: ["Colossal Dreadmaw", "Forest", "Sol Ring"], graveyard: ["Grizzly Bears"], exile: ["Eldritch Evolution"], stack: 0, pending: null });
  });

  it("the searcher may fail to find (CR 701.23b): declining with candidates on offer puts nothing onto the battlefield, and the spell is exiled", () => {
    const s = fetch(evolve(eeBoard({ user: [P("bears", GRIZZLY_BEARS)] }), "bears"), null);
    expect({ battlefield: ids(s, "user"), library: s.players.user.library.length, exile: names(s.players.user.exile) }).toEqual({ battlefield: [], library: EE_LIBRARY.length, exile: ["Eldritch Evolution"] });
  });

  it("the exile is part of resolving: countered, Eldritch Evolution goes to its owner's graveyard — and the sacrifice stays paid", () => {
    let s = eeBoard({ user: [P("courser", CENTAUR_COURSER)], aiHand: [H("counter", COUNTERSPELL)], aiPool: { U: 2 } });
    s = cast(s, "ee", (a) => a.sacCreatureId === "courser");
    s = resolveTopOfStack(cast({ ...s, priorityHolder: "ai" }, "counter", () => true, "ai"));
    expect({ stack: s.stack.length, pending: s.pendingChoice ?? null, battlefield: ids(s, "user"), graveyard: names(s.players.user.graveyard), exile: names(s.players.user.exile), library: s.players.user.library.length })
      .toEqual({ stack: 0, pending: null, battlefield: [], graveyard: ["Centaur Courser", "Eldritch Evolution"], exile: [], library: EE_LIBRARY.length });
  });

  it("⛔ with no creature to sacrifice the spell is not castable", () => {
    expect(offers(eeBoard({ user: [P("ring", SOL_RING)] }), "user", "ee")).toHaveLength(0);
  });

  it("⭐ the cost is a CREATURE as it is paid: an animated Mutavault pays it; a bestowed Aura, a God short of its devotion and a Saga with a creature back face do not", () => {
    // user: Grizzly Bears wearing a bestowed Boon Satyr, Thassa (devotion to blue 1), Fable of the Mirror-Breaker, and Mutavault
    // animated by its own ability.
    const s0 = activate(eeBoard({ user: [P("bears", GRIZZLY_BEARS, "user", { attachments: ["satyr"] }), P("satyr", BOON_SATYR, "user", { attachedTo: "bears", bestowed: true }),
      P("thassa", THASSA), P("fable", FABLE, "user", { counters: { lore: 1 } }), P("vault", MUTAVAULT)], pool: { G: 3, C: 1 } }), "user", "vault");
    const row = { victims: offers(s0, "user", "ee").map((a) => a.sacCreatureId).sort(), vaultCap: candidates(evolve(s0, "vault")) };
    console.log("  WITNESS creatureCost", JSON.stringify(row));
    expect(row).toEqual({ victims: ["bears", "vault"], vaultCap: ["Grizzly Bears", "Llanowar Elves", "Walking Ballista"] });
  });
});

describe("⚠️ the sacrificed creature's values are frozen on the spell (the shared channel could be overwritten)", () => {
  it("⭐ Eldritch Evolution sacrificing Centaur Courser, answered by Fling sacrificing Colossal Dreadmaw: the search is still 5 or less", () => {
    let s = eeBoard({ user: [P("courser", CENTAUR_COURSER)], ai: [P("maw", COLOSSAL_DREADMAW, "ai")], aiHand: [H("fling", FLING)], aiPool: { R: 2 } });
    s = cast(s, "ee", (a) => a.sacCreatureId === "courser");
    s = cast({ ...s, priorityHolder: "ai" }, "fling", (a) => a.sacCreatureId === "maw" && (a.targets || []).some((t) => t.id === "user"), "ai");
    const shared = s.sacrificedForCost.manaValue;
    s = resolveTopOfStack(s);                   // Fling: 6 damage to the caster
    const paused = resolveTopOfStack(s);        // Eldritch Evolution
    const row = { shared, life: paused.players.user.life, candidates: candidates(paused) };
    console.log("  WITNESS frozenSacrifice", JSON.stringify(row));
    expect(row).toEqual({ shared: 6, life: 34, candidates: ["Centaur Courser", "Grizzly Bears", "Hill Giant", "Llanowar Elves", "Siege Mastodon", "Walking Ballista"] });
  });

  it("the stamp is this cast's own payment only: a spell that sacrificed nothing carries none, even while the shared channel still holds an earlier one", () => {
    let s = eeBoard({ user: [P("courser", CENTAUR_COURSER)], hand: [H("ee", ELDRITCH_EVOLUTION), H("kd", KINDRED_DOMINANCE)], pool: { G: 3, B: 7 } });
    s = fetch(evolve(s, "courser"), null);
    const onStack = cast(s, "kd");
    expect({ shared: onStack.sacrificedForCost, context: Object.keys(onStack.stack[0].payload.params.context).sort() })
      .toEqual({ shared: { power: 3, toughness: 3, manaValue: 3 }, context: ["castDuringMainPhase"] });
  });

  it("a copy of the spell uses what the original sacrificed (CR 707.10): Twincast's copy searches for 5 or less too", () => {
    let s = eeBoard({ user: [P("courser", CENTAUR_COURSER)], hand: [H("ee", ELDRITCH_EVOLUTION), H("twin", TWINCAST)], pool: { G: 3, U: 3 } });
    s = cast(s, "ee", (a) => a.sacCreatureId === "courser");
    s = resolveTopOfStack(cast(s, "twin"));     // Twincast resolves: the copy is on the stack above the original
    const paused = resolveTopOfStack(s);        // the copy
    const afterCopy = fetch(paused, "Hill Giant");
    const row = { candidates: candidates(paused), copyLeft: { exile: names(afterCopy.players.user.exile), graveyard: names(afterCopy.players.user.graveyard) }, stack: afterCopy.stack.length };
    console.log("  WITNESS copy", JSON.stringify(row));
    expect(row).toEqual({ candidates: ["Centaur Courser", "Grizzly Bears", "Hill Giant", "Llanowar Elves", "Siege Mastodon", "Walking Ballista"],
      copyLeft: { exile: [], graveyard: ["Centaur Courser", "Twincast"] }, stack: 1 });
  });

  it("SYNTHETIC CONTEXT (the cap's guard): the atom resolved with no frozen sacrifice finds nothing — never an uncapped search, and never the shared channel's value", () => {
    const atom = parseEffectProgram(ELDRITCH_EVOLUTION).atoms[0];
    const s0 = { ...eeBoard(), sacrificedForCost: { power: 6, toughness: 6, manaValue: 6 } };
    const out = resolveAtom(s0, atom, ctxUser);
    const withValue = resolveAtom(s0, atom, { ...ctxUser, sacrificedForCost: { power: 0, toughness: 0, manaValue: 0 } });
    expect({ none: candidates(out), zero: candidates(withValue) }).toEqual({ none: [], zero: ["Grizzly Bears", "Llanowar Elves", "Walking Ballista"] });
  });
});
